android.extraProguardRules:
# ironSource / LevelPlay mediation core — keep all classes; the AAR's own
# consumer rules resolve from Maven at build time and are not on disk to audit,
# so we keep the ironSource-documented baseline in full.
-keep class com.ironsource.** { *; }
-dontwarn com.ironsource.**

# Parcelable CREATOR fields must survive R8 so mediation payloads deserialize.
-keepclassmembers class * implements android.os.Parcelable { public static final android.os.Parcelable$Creator *; }

# Google Mobile Ads (AdMob adapter surface reached reflectively by mediation).
-keep public class com.google.android.gms.ads.** { public *; }

# Unity Ads / unity-levelplay-mediation SDK (com.unity3d.ads-mediation:mediation-sdk).
-keep class com.unity3d.** { *; }
-dontwarn com.unity3d.**
